#include <cstdio>
#include <vector>
using namespace std;

int main() {
    while (1) {
        int n, m;
        scanf("%d %d", &n, &m);
        if (n == 0 && m == 0) {
            break;
        }
        vector<int> input(n);
        scanf("%d", &input[0]); // Read first element separately
        for (int i = 1; i < n; i++) {
            scanf("%d", &input[i]);
        }
        int now = 0;
        for (int i = 0; i < m; i++) {
            now += input[i];
        }
        int max = now;
        for (int i = m; i < n; i++) {
            now -= input[i - m];
            now += input[i];
            if (now > max) {
                max = now;
            }
        }
        printf("%d\n", max);
    }
    return 0;
}

