#include <vector>
#include <numeric> // For std::accumulate
using namespace std;

int main() {
    ios::sync_with_stdio(false); // Optimize input/output performance
    cin.tie(nullptr); // Disable automatic flushing of cout

    while (1) {
        int n, m;
        cin >> n >> m;
        if (n == 0 && m == 0) {
            break;
        }
        vector<int> input(n);
        for (int i = 0; i < n; i++) {
            cin >> input[i];
        }

        // Use std::accumulate for initial sum calculation
        int max = accumulate(input.begin(), input.begin() + m, 0);
        int now = max;

        for (int i = m; i < n; i++) {
            now += input[i] - input[i - m]; // Update sum efficiently
            if (now > max) {
                max = now;
            }
        }
        cout << max << '\n'; // Use '\n' for faster output
    }
    return 0;
}

