const int MAXN = 100000;  // Optimized size definition
int input[MAXN];

int main() {
    int n, m;
    while (scanf("%d %d", &n, &m), n || m) {  // Combined input condition to reduce lines
        for (int i = 0; i < n; i++) {
            scanf("%d", &input[i]);
        }
        int now = 0;
        for (int i = 0; i < m; i++) {
            now += input[i];
        }
        int max_sum = now;  // Renamed variable for clarity
        for (int i = m; i < n; i++) {
            now += input[i] - input[i - m];  // Simplified update in a single line
            if (now > max_sum) {
                max_sum = now;
            }
        }
        printf("%d\n", max_sum);
    }
    return 0;
}

